param([string]$BaseUrl="http://127.0.0.1:8000",[int]$ProjectId=1)
$ErrorActionPreference="Stop"
function S([string]$scope){Invoke-RestMethod -Method Post -Uri "$BaseUrl/api/v1/auth/local/demo-session" -ContentType "application/json" -Body (@{scope=$scope}|ConvertTo-Json -Compress)}
function P([string]$path,[hashtable]$body,[hashtable]$headers){Invoke-RestMethod -Method Post -Uri "$BaseUrl$path" -Headers $headers -ContentType "application/json" -Body ($body|ConvertTo-Json -Depth 12 -Compress)}
$hq=S hq;$agency=S agency;$client=S client;$hh=@{Authorization="Bearer $($hq.token)"};$ah=@{Authorization="Bearer $($agency.token)"};$ch=@{Authorization="Bearer $($client.token)"};$n=Get-Date -Format "yyyyMMddHHmmssfff";$root="/api/v1/factory-platform/projects/$ProjectId/fact-library";$f=P "$root/facts" @{fact_key="PRODUCT-FACT-$n";fact_type="product";source_reference="PRODUCT-$n";authority_reference="QUALITY-$n"} $hh;$v=P "$root/facts/$($f.id)/versions" @{fact_manifest=@{statement="Source-bound product fact";citations=@("PRODUCT-$n","QUALITY-$n")}} $hh;$v=P "$root/versions/$($v.id)/verify" @{expected_revision=$v.revision;reference="FACT-VERIFY-$n"} $ah;$r=P "$root/versions/$($v.id)/releases" @{target="geo-owner";handoff_manifest=@{consumer="geo";automatic_content_publish=$false;model_generated_fact_accepted=$false}} $hh;$r=P "$root/releases/$($r.id)/approve" @{expected_revision=$r.revision;reference="FACT-APPROVE-$n"} $ah;$r=P "$root/releases/$($r.id)/acknowledge" @{expected_revision=$r.revision;reference="FACT-RECEIPT-$n"} $ch;[pscustomobject]@{fact_status=$f.status;version_status=$v.status;release_status=$r.status;release_available=$r.available;automatic_content_publish=$false;model_generated_fact_accepted=$false;hq=$hq.user.id;agency=$agency.user.id;consumer=$client.user.id}|ConvertTo-Json
